 ResolvedCount int `json:"resolvedCount"`
 Active bool `json:"active"`
 Created time.Time `json:"created"`
 Resolved time.Time `json:"resolved"`
 Priority string `json:"priority"`
}

func getRepoPath() string {
 if p := os.Getenv("DSTASK_GIT_REPO"); p != "" {
   return p
 }
 home, _ := os.UserHomeDir()
 return filepath.Join(home, ".dstask")
}

func ensureRepo() string {
 repo := getRepoPath()
 // if not exists, init
 if _, err := os.Stat(filepath.Join(repo, ".git")); os.IsNotExist(err) {
   // create dir
   os.MkdirAll(repo, 0755)
   cmd := exec.Command("git", "init", repo)
   cmd.Stdout = os.Stderr
   cmd.Stderr = os.Stderr
   cmd.Run()
   // create subdirs
   for _, d := range []string{"active","deferred","delegated","paused","pending","recurring","resolved","template"} {
     os.MkdirAll(filepath.Join(repo, d), 0755)
   }
   // Note: original also prints Add remote message and [] ?
   // Actually after init, it prints message to stderr? Let's check earlier output: after init, it printed "Add a remote repository with: dstask git remote add origin <repo>" to stdout? In our tests, that message went to stdout? We saw it went to stdout before JSON. We need to replicate.
   // But ensureRepo is called early; we need to handle display of that message when repo was just initialized and no tasks.
   // For now, just ensure subdirs.
 }
 // ensure subdirs exist if repo exists but subdirs missing (like after clone)
 for _, d := range []string{"active","deferred","delegated","paused","pending","recurring","resolved","template"} {
   os.MkdirAll(filepath.Join(repo, d), 0755)
 }
 return repo
}

func loadIdsMap(repo string) IdsMap {
 path := filepath.Join(repo, ".git", "dstask", "ids.bin")
 f, err := os.Open(path)
 if err != nil {
   return make(IdsMap)
 }
 defer f.Close()
 dec := gob.NewDecoder(f)
 var m IdsMap
 // try decode as map[string]int
 err = dec.Decode(&m)
 if err != nil {
   // try as map[int]string and invert?
   // Actually original type is map[string]int, so if fails try other?
   f.Seek(0,0)
   dec = gob.NewDecoder(f)
   var m2 map[int]string
   err2 := dec.Decode(&m2)
   if err2 == nil {
     // invert
     m = make(IdsMap)
     for k,v := range m2 {
       m[v]=k
     }
     return m
   }
   return make(IdsMap)
 }
 return m
}

func saveIdsMap(repo string, m IdsMap) {
 dir := filepath.Join(repo, ".git", "dstask")
 os.MkdirAll(dir, 0755)
 path := filepath.Join(dir, "ids.bin")
 f, err := os.Create(path)
 if err != nil { return }
 defer f.Close()
 enc := gob.NewEncoder(f)
 enc.Encode(&m)
}

func loadState(repo string) State {
 path := filepath.Join(repo, ".git", "dstask", "state.bin")
 f, err := os.Open(path)
 if err != nil {
   return State{}
 }
 defer f.Close()
 dec := gob.NewDecoder(f)
 var s State
 err = dec.Decode(&s)
 if err != nil {
   return State{}
 }
 return s
}

func saveState(repo string, s State) {
 dir := filepath.Join(repo, ".git", "dstask")
 os.MkdirAll(dir, 0755)
 path := filepath.Join(dir, "state.bin")
 f, err := os.Create(path)
 if err != nil { return }
 defer f.Close()
 enc := gob.NewEncoder(f)
 enc.Encode(&s)
}

func parseTime(s string) (time.Time, error) {
 // try various formats, return zero if empty
 if s == "" { return time.Time{}, nil }
 // RFC3339
 if t, err := time.Parse(time.RFC3339, s); err == nil {
   return t, nil
 }
 // try without timezone? Original uses RFC3339 with nano?
 // We'll try time.RFC3339Nano
 if t, err := time.Parse(time.RFC3339Nano, s); err == nil {
   return t, nil
 }
 return time.Time{}, fmt.Errorf("parse")
}

func loadTasks(repo string) ([]Task, map[string]Task, map[string]string) {
 // returns list, map uuid->task, map uuid->status dir name
 tasks := []Task{}
 uuidToTask := make(map[string]Task)
 uuidToStatus := make(map[string]string)
 // status dirs
 dirs := []string{"pending","active","paused","resolved","template","deferred","delegated","recurring"}
 for _, status := range dirs {
   dirPath := filepath.Join(repo, status)
   files, err := os.ReadDir(dirPath)
   if err != nil { continue }
   for _, file := range files {
     if file.IsDir() { continue }
     name := file.Name()
     if !strings.HasSuffix(name, ".yml") && !strings.HasSuffix(name, ".yaml") { continue }
     uuidStr := strings.TrimSuffix(name, ".yml")
     uuidStr = strings.TrimSuffix(uuidStr, ".yaml")
     // parse file
     path := filepath.Join(dirPath, file.Name())
     content, err := os.ReadFile(path)
     if err != nil { continue }
     task, err := parseTaskYaml(content)
     if err != nil {
       // try fallback?
       continue
     }
     task.Uuid = uuidStr
     task.Status = status
     // Ensure priority default
     if task.Priority == "" { task.Priority = "P2" }
     tasks = append(tasks, task)
     uuidToTask[uuidStr] = task
     uuidToStatus[uuidStr] = status
   }
 }
 return tasks, uuidToTask, uuidToStatus
}

func parseTaskYaml(data []byte) (Task, error) {
 // Very simple yaml parser for dstask files
 // We have to handle:
 // summary: ...
 // notes: "" OR notes: | or |2- etc plus indented lines
 // tags: [] or tags:\n- ...
 // project: ...
 // priority: ...
 // delegatedto: ...
 // subtasks: []
 // dependencies: []
 // created: RFC3339
 // resolved: RFC3339
 // due: RFC3339
 task := Task{}
 lines := strings.Split(string(data), "\n")
 i := 0
 var currentList *[]string
 var inNotesBlock bool
 var notesLines []string
 var notesIndent int
 var notesFirstLineIsBlock bool
 // We need to capture state
 for i < len(lines) {
   line := lines[i]
   if line == "" {
     i++
     continue
   }
   if inNotesBlock {
     // Check if line is indented (at least 2 spaces) or empty? If not indented and contains ":", then notes block ends
     // Determine indent
     trimmedLeft := strings.TrimLeft(line, " ")
     if trimmedLeft == "" {
       notesLines = append(notesLines, "")
       i++
       continue
     }
     // If line starts with spaces and not containing colon at start? Simple heuristic: if it starts with 2 spaces, it's part of notes; else break
     if strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t") {
       // Count leading spaces
       // Remove first 2 spaces if present
       // For dstask, notes block lines are indented by 2 spaces
       // So strip 2 leading spaces
       if strings.HasPrefix(line, "  ") {
         notesLines = append(notesLines, line[2:])
       } else if strings.HasPrefix(line, " ") {
         notesLines = append(notesLines, strings.TrimPrefix(line, " "))
       } else {
         notesLines = append(notesLines, trimmedLeft)
       }
       i++
       continue
     } else {
