   return today, nil
 case "tomorrow":
   return today.AddDate(0,0,1), nil
 case "yesterday":
   return today.AddDate(0,0,-1), nil
 }
 // YYYY-MM-DD
 if t, err := time.Parse("2006-01-02", s); err == nil {
   return t.UTC(), nil
 }
 // MM-DD
 if t, err := time.Parse("01-02", s); err == nil {
   // use current year, but if month day already passed? Original seems to use 2026 for 12-25 even though now is Sep 2026 -> future this year. Need to determine year logic: if MM-DD < today month/day, next year? Let's test: today is Sep 9 2026, MM-DD 12-25 gave 2026-12-25 (future same year). For past date, what would happen? Might give current year still? We saw due:12-25 gave 2026-12-25, which is future. What about due:01-01? That would be past? Might give next year? But we don't have test. For simplicity, if parsed MM-DD gives date this year, but if it's before today, maybe next year? However original might just use current year regardless? Let's check due:01-01 today Sep -> would it give 2026-01-01 past or 2027? We haven't tested. We'll assume if date is before today, add a year? Or just use current year? Let's implement same year for now, but if before today, next year? We'll use current year and if date before today, plus one year? Need to decide. For simplicity, we'll use current year and if date is before today, use next year (common behavior).
   parsed := time.Date(today.Year(), t.Month(), t.Day(), 0,0,0,0, time.UTC)
   if parsed.Before(today) {
     parsed = parsed.AddDate(1,0,0)
   }
   return parsed, nil
 }
 // DD
 if day, err := strconv.Atoi(s); err == nil {
   if day >=1 && day <=31 {
     // Use current month/year, if day < today.Day, next month?
     parsed := time.Date(today.Year(), today.Month(), day, 0,0,0,0, time.UTC)
     if parsed.Before(today) {
       parsed = parsed.AddDate(0,1,0)
     }
     return parsed, nil
   }
 }
 // weekdays
 weekdays := map[string]time.Weekday{
   "monday": time.Monday,
   "tuesday": time.Tuesday,
   "wednesday": time.Wednesday,
   "thursday": time.Thursday,
   "friday": time.Friday,
   "saturday": time.Saturday,
   "sunday": time.Sunday,
 }
 // Handle next-monday etc
 if strings.HasPrefix(s, "next-") {
   dayName := strings.TrimPrefix(s, "next-")
   if wd, ok := weekdays[dayName]; ok {
     // next weekday = next occurrence of that weekday that is not today, plus if it's next- then add 7 days after the next occurrence? Actually original: Monday today is Tuesday? Let's test.
     // We observed: when today is Tuesday (Sep 9 2026 is Tuesday? Let's check: 2026-09-09 is Wednesday? Earlier output said Wed 9 Sep 2026. So today Wednesday Sep 9 2026.
     // due:monday gave 2026-09-14 (next Monday) which is 5 days after today Wed. due:next-monday also gave 2026-09-14 same. So "next-monday" == "monday" meaning next occurrence.
     // So for monday, from Wed Sep 9, next Monday is Sep 14 (5 days). So implementation: find next weekday after today (not today). Even if today is Monday, next Monday would be 7 days later.
     daysAhead := (int(wd) - int(today.Weekday()) + 7) % 7
     if daysAhead == 0 {
       daysAhead = 7
     }
     return today.AddDate(0,0,daysAhead), nil
   }
 }
 if wd, ok := weekdays[s]; ok {
   daysAhead := (int(wd) - int(today.Weekday()) + 7) % 7
   if daysAhead == 0 {
     daysAhead = 7
   }
   return today.AddDate(0,0,daysAhead), nil
 }

