func formatDueTable(due time.Time, now time.Time) string {
 if due.IsZero() || due.Year() == 1 {
   return ""
 }
 // Compare with today midnight UTC
 utcNow := now.UTC()
 today := time.Date(utcNow.Year(), utcNow.Month(), utcNow.Day(), 0,0,0,0, time.UTC)
 dueDay := time.Date(due.Year(), due.Month(), due.Day(), 0,0,0,0, time.UTC)
 diff := int(dueDay.Sub(today).Hours()/24)
 if diff == 0 {
   return "today"
 }
 if diff == 1 {
   return "tomorrow"
 }
 if diff == -1 {
   return "yesterday"
 }
 // Format as "2 Jan 2006"
 return dueDay.Format("2 Jan 2006")
}

func priorityOrder(p string) int {
 switch p {
 case "P0": return 0
 case "P1": return 1
 case "P2": return 2
 case "P3": return 3
 default: return 2
 }
}

func sortTasks(tasks []Task) {
 sort.Slice(tasks, func(i,j int) bool {
   pi := priorityOrder(tasks[i].Priority)
   pj := priorityOrder(tasks[j].Priority)
   if pi != pj { return pi < pj }
   if !tasks[i].Created.Equal(tasks[j].Created) {
     return tasks[i].Created.Before(tasks[j].Created)
   }
   return tasks[i].Id < tasks[j].Id
 })
}

func filterTasks(tasks []Task, query Query) []Task {
 // Apply project, tags, antitags, due, priority, text
 res := []Task{}
 for _, t := range tasks {
   // Project filter
   if query.Project != "" {
     if t.Project != query.Project {
       continue
     }
   }
   if len(query.AntiProjects) > 0 {
     skip := false
     for _, ap := range query.AntiProjects {
       if t.Project == ap {
         skip = true
         break
       }
     }
     if skip { continue }
   }
   // Tags
   if len(query.Tags) > 0 {
     // Must have all tags
     hasAll := true
     for _, qt := range query.Tags {
       found := false
       for _, tt := range t.Tags {
         if tt == qt { found = true; break }
       }
       if !found { hasAll = false; break }
     }
     if !hasAll { continue }
   }
   if len(query.AntiTags) > 0 {
     skip := false
     for _, at := range query.AntiTags {
       for _, tt := range t.Tags {
         if tt == at { skip = true; break }
       }
     }
     if skip { continue }
   }
   // Due
   if !query.Due.IsZero() {
     // Compare due dates by day?
     if t.Due.IsZero() { continue }
     // Compare year month day?
     if t.Due.Year() != query.Due.Year() || t.Due.Month() != query.Due.Month() || t.Due.Day() != query.Due.Day() {
       continue
     }
   }
   // Priority
   if query.Priority != "" {
     if t.Priority != query.Priority {
       continue
     }
   }
   // Text filter
   if query.Text != "" {
     // case-insensitive substring search in summary and notes
     lowerText := strings.ToLower(query.Text)
     if !strings.Contains(strings.ToLower(t.Summary), lowerText) && !strings.Contains(strings.ToLower(t.Notes), lowerText) {
       continue
     }
   }
   res = append(res, t)
 }
 return res
}

func loadAndAssignIds(repo string, tasks []Task, idMap IdsMap) []Task {
 // idMap is uuid->id from file, but if missing or empty, assign based on UUID lexical sort, but also need to handle that map may contain entries that no longer exist (removed tasks). So we need to rebuild?
 // Logic observed:
 // - If ids.bin exists and is non-empty, use its mapping for existing files, and assign new IDs for files not in map, reusing lowest free ID.
 // - If ids.bin missing, assign IDs based on UUID lexical sort, starting 1..n, but do NOT save ids.bin automatically (only on add? Later test showed after show-open without ids.bin, file still missing. But after add, file created with mapping that includes all existing + new). So for show operations, if ids.bin missing, we should NOT create file, just assign temporary IDs for display.
 // However, for simplicity, we will if ids.bin missing, assign IDs based on UUID lexical sort for display, and when adding new task, we will create ids.bin with proper mapping including all tasks.
 // Also need to handle that after removal, map entry removed and ID freed.
 // For tasks loading, we have tasks with no ID yet. We'll assign.

 // If idMap empty (missing file), assign IDs based on UUID lexical sort
 if len(idMap) == 0 {
   // collect all open tasks (non-resolved) uuids
   // Actually resolved tasks should have ID 0, not included.
   // Open tasks are those with status != resolved
   openUuids := []string{}
   for _, t := range tasks {
     if t.Status != "resolved" {
       openUuids = append(openUuids, t.Uuid)
     }
   }
   sort.Strings(openUuids)
   tmpMap := make(map[string]int)
   for i, u := range openUuids {
     tmpMap[u] = i+1
   }
   // assign to tasks
   for idx := range tasks {
     if tasks[idx].Status == "resolved" {
       tasks[idx].Id = 0
     } else {
       if id, ok := tmpMap[tasks[idx].Uuid]; ok {
         tasks[idx].Id = id
       }
     }
   }
   return tasks
 } else {
   // Use existing map, but also ensure all open tasks have mapping; if not, assign new IDs reusing gaps
   // First, collect used IDs from map for uuids that still exist as open
   usedIds := make(map[int]bool)
   uuidExists := make(map[string]bool)
   for _, t := range tasks {
     if t.Status != "resolved" {
       uuidExists[t.Uuid] = true
     }
   }
   // Clean map from non-existing uuids
   cleaned := make(IdsMap)
   for uuid, id := range idMap {
     if uuidExists[uuid] {
       cleaned[uuid]=id
       usedIds[id]=true
     }
   }
   // For tasks not in cleaned, assign smallest free ID
   // Find max ID
   maxId := 0
   for _, id := range cleaned {
     if id > maxId { maxId = id }
   }
   // For each task not in cleaned, assign
   for idx := range tasks {
     if tasks[idx].Status == "resolved" {
       tasks[idx].Id = 0
       continue
     }
     if id, ok := cleaned[tasks[idx].Uuid]; ok {
       tasks[idx].Id = id
     } else {
       // find smallest free
       newId := 1
       for {
         if !usedIds[newId] { break }
         newId++
       }
       cleaned[tasks[idx].Uuid]=newId
       usedIds[newId]=true
       tasks[idx].Id = newId
       if newId > maxId { maxId = newId }
     }
   }
   // Note: we do NOT save cleaned here unless caller wants to (e.g., after add)
   return tasks
 }
}

func buildIdMapFromTasks(tasks []Task) IdsMap {
 m := make(IdsMap)
 for _, t := range tasks {
   if t.Status != "resolved" && t.Id != 0 {
     m[t.Uuid]=t.Id
   }
 }
 return m
}

