   for _, file := range files {
     if file.IsDir() { continue }
     name := file.Name()
     if !strings.HasSuffix(name, ".yml") && !strings.HasSuffix(name, ".yaml") { continue }
     uuidStr := strings.TrimSuffix(name, ".yml")
     uuidStr = strings.TrimSuffix(uuidStr, ".yaml")
     // parse file
     path := filepath.Join(dirPath, file.Name())
     content, err := os.ReadFile(path)
     if err != nil { continue }
