func parseTaskYaml(data []byte) (Task, error) {
 // Very simple yaml parser for dstask files
 // We have to handle:
 // summary: ...
 // notes: "" OR notes: | or |2- etc plus indented lines
 // tags: [] or tags:\n- ...
 // project: ...
 // priority: ...
 // delegatedto: ...
 // subtasks: []
 // dependencies: []
 // created: RFC3339
 // resolved: RFC3339
 // due: RFC3339
 task := Task{}
 lines := strings.Split(string(data), "\n")
 i := 0
 var currentList *[]string
 var inNotesBlock bool
 var notesLines []string
 var notesIndent int
 var notesFirstLineIsBlock bool
 // We need to capture state
 for i < len(lines) {
   line := lines[i]
   if line == "" {
     i++
     continue
   }
   if inNotesBlock {
     // Check if line is indented (at least 2 spaces) or empty? If not indented and contains ":", then notes block ends
     // Determine indent
     trimmedLeft := strings.TrimLeft(line, " ")
     if trimmedLeft == "" {
       notesLines = append(notesLines, "")
       i++
       continue
     }
     // If line starts with spaces and not containing colon at start? Simple heuristic: if it starts with 2 spaces, it's part of notes; else break
     if strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t") {
       // Count leading spaces
       // Remove first 2 spaces if present
       // For dstask, notes block lines are indented by 2 spaces
       // So strip 2 leading spaces
       if strings.HasPrefix(line, "  ") {
         notesLines = append(notesLines, line[2:])
       } else if strings.HasPrefix(line, " ") {
         notesLines = append(notesLines, strings.TrimPrefix(line, " "))
       } else {
         notesLines = append(notesLines, trimmedLeft)
       }
       i++
       continue
     } else {
       // Not indented, so it's next key
       inNotesBlock = false
       // Set task.Notes from notesLines
       // Join with \n
       task.Notes = strings.Join(notesLines, "\n")
       // Note: if original had |2- then trailing newlines trimmed? We'll handle later
       // continue processing this line as normal
       // Don't increment i yet, fall through
     }
   }

   // Handle current list accumulation
   if currentList != nil {
     trimmed := strings.TrimSpace(line)
     if strings.HasPrefix(trimmed, "- ") {
       val := strings.TrimPrefix(trimmed, "- ")
       val = strings.Trim(val, "\"")
       *currentList = append(*currentList, val)
       i++
       continue
     } else if trimmed == "[]" || trimmed == "" {
       // end of list?
       if trimmed == "[]" {
         i++
       }
       currentList = nil
       continue
     } else if strings.Contains(line, ":") {
       // new key, end list
       currentList = nil
       // fall through
     } else {
       i++
       continue
     }
   }

   // Parse key: value
   // Find first colon
   colonIdx := strings.Index(line, ":")
   if colonIdx == -1 {
     i++
     continue
   }
   key := strings.TrimSpace(line[:colonIdx])
   valPart := strings.TrimSpace(line[colonIdx+1:])

   switch key {
   case "summary":
     // valPart may be empty? Then summary is rest? In dstask yaml, summary is single line after colon space
     task.Summary = strings.Trim(valPart, "\"")
   case "notes":
     if valPart == "\"\"" || valPart == "''" || valPart == "" {
       if valPart == "\"\"" || valPart == "''" {
         task.Notes = ""
       } else {
         // Could be empty and next line is list? But notes is string, not list
         // Check if next line is not indented list -> treat as empty?
         // Could be block indicator
         // Actually notes: "" is empty, notes: | or |2- or |-
         // We need to detect block
         // If valPart == "" then maybe next lines are block? But we saw notes: "" always with quotes
         // If valPart starts with "|" then block begins
         task.Notes = ""
       }
       if strings.HasPrefix(valPart, "|") {
         // block literal
         notesFirstLineIsBlock = true
         inNotesBlock = true
         notesLines = []string{}
         // The block indicator may be |, |-, |2-, etc, but content starts next line
         // So proceed to next line
         i++
         continue
       }
     } else {
       if strings.HasPrefix(valPart, "|") {
         inNotesBlock = true
         notesLines = []string{}
         notesFirstLineIsBlock = true
         i++
         continue
       } else {
         // Single line note with maybe quotes?
         task.Notes = strings.Trim(valPart, "\"")
       }
     }
   case "tags":
     if valPart == "[]" {
       task.Tags = []string{}
     } else if valPart == "" {
       // Next lines are list
       task.Tags = []string{}
       currentList = &task.Tags
       // We'll process next line
     } else {
       // Inline?
       // Could be list inline? Not observed
       task.Tags = []string{}
       if strings.HasPrefix(valPart, "[") {
         // parse?
       }
     }
   case "project":
     task.Project = strings.Trim(valPart, "\"")
   case "priority":
     task.Priority = strings.Trim(valPart, "\"")
   case "delegatedto":
     task.DelegatedTo = strings.Trim(valPart, "\"")
   case "subtasks":
     // ignore
     if valPart == "[]" {
     } else if valPart == "" {
       // list
       var dummy []string
       currentList = &dummy
     }
   case "dependencies":
     if valPart == "[]" {
     } else if valPart == "" {
       var dummy []string
       currentList = &dummy
     }
   case "created":
     if valPart != "" {
       if t, err := time.Parse(time.RFC3339Nano, valPart); err == nil {
         task.Created = t
       } else if t, err := time.Parse(time.RFC3339, valPart); err == nil {
         task.Created = t
       } else {
         // try without nano?
         if t, err := time.Parse("2006-01-02T15:04:05Z", valPart); err == nil {
           task.Created = t
         }
       }
     }
   case "resolved":
     if valPart != "" {
       if t, err := time.Parse(time.RFC3339Nano, valPart); err == nil {
         task.Resolved = t
       } else if t, err := time.Parse(time.RFC3339, valPart); err == nil {
         task.Resolved = t
       } else {
         if t, err := time.Parse("2006-01-02T15:04:05Z", valPart); err == nil {
           task.Resolved = t
         }
       }
     }
   case "due":
     if valPart != "" {
       if t, err := time.Parse(time.RFC3339Nano, valPart); err == nil {
         task.Due = t
       } else if t, err := time.Parse(time.RFC3339, valPart); err == nil {
         task.Due = t
       } else {
         if t, err := time.Parse("2006-01-02T15:04:05Z", valPart); err == nil {
           task.Due = t
         }
       }
     }
   }
   i++
 }
 if inNotesBlock {
   task.Notes = strings.Join(notesLines, "\n")
 }
 // Trim notes if it has trailing newline from block? The yaml block may preserve newline, but we have joined lines with \n; if original had blank line at end, we keep.
 // For notes that were "" we already set empty
 // Special handling: if notes block had first line empty due to |2-? Actually notes we observed: notes: |2- \n\n  stop note... So first line after indicator may be empty? In that case notesLines first entry empty. Our parsing will produce "\nstop note..."? Let's check observed: file with notes: |2-\n\n  stopping note\n . That should result in notes "\nstop note..."? In earlier output we saw "\nstopping note". Yes first line empty.
 // Our parsing: after indicator, we set notesLines empty, then next line is empty string (blank line) -> we append "" . Then next line "  stop note" -> append "stop note". Join with "\n" gives "\nstop note". That's correct.

 // Also need to handle notes: "" -> should be empty string, but we set.
 return task, nil
}

