func parseArgsForQuery(args []string) Query {
 q := Query{}
 for _, a := range args {
   if a=="--" {
     q.IgnoreContext=true
     continue
   }
   if strings.HasPrefix(a, "+") {
     tag := strings.TrimPrefix(a, "+")
     if tag!="" { q.Tags=append(q.Tags, tag) }
     continue
   }
   if strings.HasPrefix(a, "-project:") {
     proj := strings.TrimPrefix(a, "-project:")
     q.AntiProjects=append(q.AntiProjects, proj)
     continue
   }
   if strings.HasPrefix(a, "-") {
     tag := strings.TrimPrefix(a, "-")
     if tag!="" { q.AntiTags=append(q.AntiTags, tag) }
     continue
   }
   if strings.HasPrefix(a, "project:") {
     proj := strings.TrimPrefix(a, "project:")
     q.Project=proj
     continue
   }
   if strings.HasPrefix(a, "due:") {
     dueStr := strings.TrimPrefix(a, "due:")
     if dueStr=="" {
       q.Due=time.Time{}
     } else {
       if t, err := parseDue(dueStr); err==nil {
         q.Due=t
       }
     }
     continue
   }
   if a=="P0"||a=="P1"||a=="P2"||a=="P3" {
     q.Priority=a
     continue
   }
   if strings.HasPrefix(a, "template:") {
     tmplStr := strings.TrimPrefix(a, "template:")
     if id, err := strconv.Atoi(tmplStr); err==nil {
       q.Template=id
     }
     continue
   }
   if q.Text != "" { q.Text += " " }
   q.Text += a
 }
 return q
}

type AddParseResult struct {
 Summary string
 Notes string
 Tags []string
 Project string
 ProjectSet bool
 Priority string
 Due time.Time
 DueSet bool
 TemplateId int
 IgnoreContext bool
}

func parseAddArgs(args []string) (AddParseResult, error) {
 res := AddParseResult{Priority: "P2"}
 slashIdx := -1
 for i, a := range args {
   if a=="/" {
     slashIdx=i
     break
   }
 }
 var before []string
 var after []string
 if slashIdx!=-1 {
   before=args[:slashIdx]
   after=args[slashIdx+1:]
   res.Notes=strings.Join(after, " ")
 } else {
   before=args
 }
 filtered:=[]string{}
 for _, a := range before {
   if a=="--" {
     res.IgnoreContext=true
   } else {
     filtered=append(filtered, a)
   }
 }
 before=filtered
 var summaryWords []string
 for _, a := range before {
   if strings.HasPrefix(a, "+") {
     tag:=strings.TrimPrefix(a, "+")
     if tag!="" { res.Tags=append(res.Tags, tag) }
     continue
   }
   if strings.HasPrefix(a, "-") {
     tag:=strings.TrimPrefix(a, "-")
     newTags:=[]string{}
     for _, t := range res.Tags {
       if t!=tag { newTags=append(newTags, t) }
     }
     res.Tags=newTags
     continue
   }
   if strings.HasPrefix(a, "project:") {
     proj:=strings.TrimPrefix(a, "project:")
     res.Project=proj
     res.ProjectSet=true
     continue
   }
   if strings.HasPrefix(a, "due:") {
     dueStr:=strings.TrimPrefix(a, "due:")
     if dueStr=="" {
       res.Due=time.Time{}
       res.DueSet=true
     } else {
       t, err:=parseDue(dueStr)
       if err!=nil { return res, err }
       res.Due=t
       res.DueSet=true
     }
     continue
   }
   if a=="P0"||a=="P1"||a=="P2"||a=="P3" {
     res.Priority=a
     continue
   }
   if strings.HasPrefix(a, "template:") {
     tmplStr:=strings.TrimPrefix(a, "template:")
     if id, err:=strconv.Atoi(tmplStr); err==nil {
       res.TemplateId=id
     }
     continue
   }
   summaryWords=append(summaryWords, a)
 }
 res.Summary=strings.Join(summaryWords, " ")
 return res, nil
}

