func getPriorityColor(priority, status string) (string,string) {
 // returns fg, bg
 // priority colors for pending:
 // P0 fg160 bg233, P1 fg166 bg232, P2 fg250 bg233, P3 fg245 bg232
 // active: bg250, fg depends: P0 124, P1 130, P2 233, P3 ? let's guess 245? but need to find.
 // paused: bg236, fg same as pending fg but bg236: P0 160/236, P1 166/236, P2 250/236, P3 245/236
 // We'll implement as per observations.

 if status=="active" {
   bg:="250"
   var fg string
   switch priority {
   case "P0": fg="124"
   case "P1": fg="130"
   case "P2": fg="233"
   case "P3": fg="245"
   default: fg="233"
   }
   return fg, bg
 }
 if status=="paused" {
   bg:="236"
   var fg string
   switch priority {
   case "P0": fg="160"
   case "P1": fg="166"
   case "P2": fg="250"
   case "P3": fg="245"
   default: fg="250"
   }
   return fg, bg
 }
 // pending, template? template maybe same as pending?
 switch priority {
 case "P0": return "160","233"
 case "P1": return "166","232"
 case "P2": return "250","233"
 case "P3": return "245","232"
 default: return "250","233"
 }
}

