func parseTaskYaml(data []byte) (Task, error) {
 task := Task{}
 lines := strings.Split(string(data), "\n")
 i := 0
 var currentList *[]string
 var inNotesBlock bool
 var notesLines []string
 for i < len(lines) {
   line := lines[i]
   if line == "" {
     if inNotesBlock {
       notesLines = append(notesLines, "")
     }
     i++
     continue
   }
   if inNotesBlock {
     if strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t") {
       // strip 2 spaces
       if strings.HasPrefix(line, "  ") {
         notesLines = append(notesLines, line[2:])
       } else {
         notesLines = append(notesLines, strings.TrimLeft(line, " "))
       }
       i++
       continue
     } else {
       inNotesBlock = false
       task.Notes = strings.Join(notesLines, "\n")
     }
   }
   if currentList != nil {
     trimmed := strings.TrimSpace(line)
     if strings.HasPrefix(trimmed, "- ") {
       val := strings.TrimSpace(strings.TrimPrefix(trimmed, "- "))
       val = strings.Trim(val, "\"")
       *currentList = append(*currentList, val)
       i++
       continue
     } else if trimmed == "[]" {
       i++
       currentList = nil
       continue
     } else if strings.Contains(line, ":") {
       currentList = nil
     } else {
       i++
       continue
     }
   }
   colonIdx := strings.Index(line, ":")
   if colonIdx == -1 {
     i++
     continue
   }
   key := strings.TrimSpace(line[:colonIdx])
   valPart := strings.TrimSpace(line[colonIdx+1:])
   switch key {
   case "summary":
     task.Summary = strings.Trim(valPart, "\"")
   case "notes":
     if strings.HasPrefix(valPart, "|") {
       inNotesBlock = true
       notesLines = []string{}
       i++
       continue
     } else {
       if valPart == "\"\"" || valPart == "''" {
         task.Notes = ""
       } else {
         task.Notes = strings.Trim(valPart, "\"")
       }
     }
   case "tags":
     if valPart == "[]" {
       task.Tags = []string{}
     } else if valPart == "" {
       task.Tags = []string{}
       currentList = &task.Tags
     }
   case "project":
     task.Project = strings.Trim(valPart, "\"")
   case "priority":
     task.Priority = strings.Trim(valPart, "\"")
   case "delegatedto":
     task.DelegatedTo = strings.Trim(valPart, "\"")
   case "subtasks":
     if valPart == "" {
       var dummy []string
       currentList = &dummy
     }
   case "dependencies":
     if valPart == "" {
       var dummy []string
       currentList = &dummy
     }
   case "created":
     if valPart != "" {
       if t, err := time.Parse(time.RFC3339Nano, valPart); err == nil {
         task.Created = t
       } else if t, err := time.Parse(time.RFC3339, valPart); err == nil {
         task.Created = t
       }
     }
   case "resolved":
     if valPart != "" {
       if t, err := time.Parse(time.RFC3339Nano, valPart); err == nil {
         task.Resolved = t
       } else if t, err := time.Parse(time.RFC3339, valPart); err == nil {
         task.Resolved = t
       }
     }
   case "due":
     if valPart != "" {
       if t, err := time.Parse(time.RFC3339Nano, valPart); err == nil {
         task.Due = t
       } else if t, err := time.Parse(time.RFC3339, valPart); err == nil {
         task.Due = t
       }
     }
   }
   i++
 }
 if inNotesBlock {
   task.Notes = strings.Join(notesLines, "\n")
 }
 if task.Priority == "" {
   task.Priority = "P2"
 }
 return task, nil
}

func writeTaskYaml(task Task) []byte {
 var sb strings.Builder
 sb.WriteString(fmt.Sprintf("summary: %s\n", task.Summary))
 if task.Notes == "" {
   sb.WriteString("notes: \"\"\n")
 } else {
   if strings.Contains(task.Notes, "\n") {
     sb.WriteString("notes: |2-\n")
     lines := strings.Split(task.Notes, "\n")
     for _, l := range lines {
       if l == "" {
         sb.WriteString("\n")
       } else {
         sb.WriteString("  " + l + "\n")
       }
     }
   } else {
     sb.WriteString(fmt.Sprintf("notes: %s\n", task.Notes))
   }
 }
 if len(task.Tags) == 0 {
   sb.WriteString("tags: []\n")
 } else {
   sb.WriteString("tags:\n")
   for _, t := range task.Tags {
     sb.WriteString(fmt.Sprintf("- %s\n", t))
   }
 }
 sb.WriteString(fmt.Sprintf("project: %s\n", task.Project))
 sb.WriteString(fmt.Sprintf("priority: %s\n", task.Priority))
 sb.WriteString(fmt.Sprintf("delegatedto: \"%s\"\n", task.DelegatedTo))
 sb.WriteString("subtasks: []\n")
 sb.WriteString("dependencies: []\n")
 if task.Created.IsZero() {
   task.Created = time.Now()
 }
 sb.WriteString(fmt.Sprintf("created: %s\n", task.Created.Format(time.RFC3339Nano)))
 if task.Resolved.IsZero() {
   sb.WriteString("resolved: 0001-01-01T00:00:00Z\n")
 } else {
   sb.WriteString(fmt.Sprintf("resolved: %s\n", task.Resolved.Format(time.RFC3339Nano)))
 }
 if task.Due.IsZero() {
   sb.WriteString("due: 0001-01-01T00:00:00Z\n")
 } else {
   sb.WriteString(fmt.Sprintf("due: %s\n", task.Due.Format(time.RFC3339Nano)))
 }
 return []byte(sb.String())
}

func isTerminal() bool {
 if os.Getenv("DSTASK_FAKE_PTY") != "" {
   return true
 }
