func findTaskById(tasks []Task, id int) (Task, bool) {
	for _, t := range tasks {
		if t.Id == id {
			return t, true
		}
	}
	return Task{}, false
}

func main() {
	repoPath := getRepoPath()
	repoExists := false
	if _, err := os.Stat(filepath.Join(repoPath, ".git")); err == nil {
		repoExists = true
	}
	repo, _ := ensureRepo()

	allTasks, uuidToStatus, _ := loadTasks(repo)
	idMap := loadIdsMap(repo)
	tasksWithIds, cleanedMap := loadAndAssignIds(repo, allTasks, idMap)

	args := os.Args[1:]

	commands := map[string]bool{
		"next": true, "add": true, "template": true, "log": true, "start": true,
		"note": true, "notes": true, "stop": true, "done": true, "resolve": true,
		"context": true, "modify": true, "edit": true, "undo": true, "sync": true,
		"open": true, "git": true, "remove": true, "rm": true,
		"show-projects": true, "show-tags": true, "show-active": true, "show-paused": true,
		"show-open": true, "show-next": true, "show-resolved": true, "show-templates": true,
		"show-unorganised": true, "show-unorganized": true,
		"bash-completion": true, "fish-completion": true, "zsh-completion": true,
		"powershell-completion": true, "help": true, "version": true,
		"_completions": true, "resolved": true,
	}

	var ids []int
	var cmd string
	var remainder []string
	cmdIdx := -1
	for i, a := range args {
		lower := strings.ToLower(a)
		if commands[lower] {
			cmdIdx = i
			cmd = lower
			break
		}
	}
	if cmdIdx == -1 {
		var possIds []int
		var filterArgs []string
		for _, a := range args {
			if a == "--" {
				filterArgs = append(filterArgs, a)
				continue
			}
			if id, err := strconv.Atoi(a); err == nil {
				possIds = append(possIds, id)
			} else {
				filterArgs = append(filterArgs, a)
			}
		}
		if len(possIds) > 0 {
			ids = possIds
			remainder = filterArgs
			cmd = "next"
		} else {
			cmd = "next"
			remainder = args
		}
	} else {
		for i := 0; i < cmdIdx; i++ {
			if id, err := strconv.Atoi(args[i]); err == nil {
				ids = append(ids, id)
			}
		}
		j := cmdIdx + 1
		for j < len(args) {
			a := args[j]
			if a == "--" {
				break
			}
			if _, err := strconv.Atoi(a); err == nil {
				id, _ := strconv.Atoi(a)
				ids = append(ids, id)
				j++
			} else {
				break
			}
		}
		remainder = args[j:]
	}

	ignoreCtx := false
	for _, a := range remainder {
		if a == "--" {
			ignoreCtx = true
			break
		}
	}
	var filterArgsWithoutIgnore []string
	for _, a := range remainder {
		if a != "--" {
			filterArgsWithoutIgnore = append(filterArgsWithoutIgnore, a)
		}
	}

	ctxQuery, fromEnv := getContext(repo)
	if ignoreCtx {
		ctxQuery = Query{IgnoreContext: true}
	}

	if !repoExists {
		if cmd == "next" || cmd == "show-open" || cmd == "show-next" || cmd == "show-active" || cmd == "show-paused" || cmd == "show-projects" || cmd == "show-tags" || cmd == "show-resolved" || cmd == "show-templates" || cmd == "show-unorganised" {
