			}
		}
	}

	// helpers
	filterQuery := parseQuery(filterArgsWithoutIgnore)
	effectiveQuery := Query{}
	if !ignoreCtx {
		effectiveQuery = ctxQuery
		effectiveQuery.Tags = append(effectiveQuery.Tags, filterQuery.Tags...)
		effectiveQuery.AntiTags = append(effectiveQuery.AntiTags, filterQuery.AntiTags...)
		if filterQuery.Project != "" {
			effectiveQuery.Project = filterQuery.Project
		}
		effectiveQuery.AntiProjects = append(effectiveQuery.AntiProjects, filterQuery.AntiProjects...)
		if !filterQuery.Due.IsZero() {
			effectiveQuery.Due = filterQuery.Due
		}
		if filterQuery.Priority != "" {
			effectiveQuery.Priority = filterQuery.Priority
		}
