	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("summary: %s\n", task.Summary))
	if task.Notes == "" {
		sb.WriteString("notes: \"\"\n")
	} else {
		if strings.Contains(task.Notes, "\n") {
			sb.WriteString("notes: |2-\n")
			lines := strings.Split(task.Notes, "\n")
			for _, l := range lines {
				if l == "" {
					sb.WriteString("\n")
				} else {
					sb.WriteString("  " + l + "\n")
				}
			}
		} else {
			sb.WriteString(fmt.Sprintf("notes: %s\n", task.Notes))
		}
	}
	if len(task.Tags) == 0 {
		sb.WriteString("tags: []\n")
	} else {
		sb.WriteString("tags:\n")
		for _, t := range task.Tags {
			sb.WriteString(fmt.Sprintf("- %s\n", t))
		}
	}
	sb.WriteString(fmt.Sprintf("project: %s\n", task.Project))
	sb.WriteString(fmt.Sprintf("priority: %s\n", task.Priority))
	sb.WriteString(fmt.Sprintf("delegatedto: \"%s\"\n", task.DelegatedTo))
	sb.WriteString("subtasks: []\n")
	sb.WriteString("dependencies: []\n")
	if task.Created.IsZero() {
		task.Created = time.Now()
	}
	sb.WriteString(fmt.Sprintf("created: %s\n", task.Created.Format(time.RFC3339Nano)))
	if task.Resolved.IsZero() {
		sb.WriteString("resolved: 0001-01-01T00:00:00Z\n")
	} else {
		sb.WriteString(fmt.Sprintf("resolved: %s\n", task.Resolved.Format(time.RFC3339Nano)))
	}
	if task.Due.IsZero() {
		sb.WriteString("due: 0001-01-01T00:00:00Z\n")
	} else {
		sb.WriteString(fmt.Sprintf("due: %s\n", task.Due.Format(time.RFC3339Nano)))
	}
	return []byte(sb.String())
}

func isTerminal() bool {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return true
	}
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func parseDue(s string) (time.Time, error) {
	orig := s
	s = strings.ToLower(strings.TrimSpace(s))
	now := time.Now()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	switch s {
	case "today":
		return today, nil
	case "tomorrow":
		return today.AddDate(0, 0, 1), nil
	case "yesterday":
		return today.AddDate(0, 0, -1), nil
	}
	if t, err := time.Parse("2006-01-02", s); err == nil {
		return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.UTC), nil
	}
	if t, err := time.Parse("01-02", s); err == nil {
		parsed := time.Date(today.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.UTC)
		if parsed.Before(today) {
			parsed = parsed.AddDate(1, 0, 0)
		}
		return parsed, nil
	}
	if day, err := strconv.Atoi(s); err == nil {
		if day >= 1 && day <= 31 {
			parsed := time.Date(today.Year(), today.Month(), day, 0, 0, 0, 0, time.UTC)
			if parsed.Before(today) {
				parsed = parsed.AddDate(0, 1, 0)
			}
			return parsed, nil
		}
	}
	weekdays := map[string]time.Weekday{
		"monday": time.Monday, "tuesday": time.Tuesday, "wednesday": time.Wednesday,
		"thursday": time.Thursday, "friday": time.Friday, "saturday": time.Saturday, "sunday": time.Sunday,
	}
	trim := strings.TrimPrefix(s, "next-")
	if wd, ok := weekdays[trim]; ok {
		daysAhead := (int(wd) - int(today.Weekday()) + 7) % 7
		if daysAhead == 0 {
			daysAhead = 7
		}
		return today.AddDate(0, 0, daysAhead), nil
	}
	return time.Time{}, fmt.Errorf("Invalid due date format: %s\nExpected format: YYYY-MM-DD, MM-DD or DD, relative date like 'next-monday', 'today', etc.", orig)
}

func formatDueTable(due time.Time) string {
	if due.IsZero() || due.Year() == 1 {
		return ""
	}
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	dueDay := time.Date(due.Year(), due.Month(), due.Day(), 0, 0, 0, 0, time.UTC)
	diff := int(dueDay.Sub(today).Hours() / 24)
	if diff == 0 {
		return "today"
	}
	if diff == 1 {
		return "tomorrow"
	}
	if diff == -1 {
		return "yesterday"
	}
	return dueDay.Format("2 Jan 2006")
}

func priorityOrder(p string) int {
	switch p {
	case "P0":
		return 0
	case "P1":
		return 1
	case "P2":
		return 2
	case "P3":
		return 3
	default:
		return 2
	}
}

func sortTasks(tasks []Task) {
	sort.Slice(tasks, func(i, j int) bool {
		pi := priorityOrder(tasks[i].Priority)
		pj := priorityOrder(tasks[j].Priority)
		if pi != pj {
			return pi < pj
		}
		if !tasks[i].Created.Equal(tasks[j].Created) {
			return tasks[i].Created.Before(tasks[j].Created)
		}
		return tasks[i].Id < tasks[j].Id
	})
}

func filterTasks(tasks []Task, q Query) []Task {
	res := []Task{}
	for _, t := range tasks {
		if q.Project != "" {
			if t.Project != q.Project {
				continue
			}
		}
		if len(q.AntiProjects) > 0 {
			skip := false
			for _, ap := range q.AntiProjects {
				if t.Project == ap {
					skip = true
					break
				}
			}
			if skip {
				continue
			}
		}
		if len(q.Tags) > 0 {
			hasAll := true
			for _, qt := range q.Tags {
				found := false
				for _, tt := range t.Tags {
					if tt == qt {
						found = true
						break
					}
				}
				if !found {
					hasAll = false
					break
				}
			}
			if !hasAll {
				continue
			}
		}
		if len(q.AntiTags) > 0 {
			skip := false
			for _, at := range q.AntiTags {
				for _, tt := range t.Tags {
					if tt == at {
						skip = true
						break
					}
				}
				if skip {
					break
				}
			}
			if skip {
				continue
			}
		}
		if !q.Due.IsZero() {
			if t.Due.IsZero() {
				continue
			}
			if t.Due.Year() != q.Due.Year() || t.Due.Month() != q.Due.Month() || t.Due.Day() != q.Due.Day() {
				continue
			}
		}
		if q.Priority != "" {
			if t.Priority != q.Priority {
				continue
			}
		}
		if q.Text != "" {
			lower := strings.ToLower(q.Text)
			if !strings.Contains(strings.ToLower(t.Summary), lower) && !strings.Contains(strings.ToLower(t.Notes), lower) {
				continue
			}
		}
		res = append(res, t)
	}
	return res
}

func loadTasks(repo string) ([]Task, map[string]string, map[string]Task) {
	var all []Task
	uuidToStatus := make(map[string]string)
	uuidToTask := make(map[string]Task)
	statuses := []string{"pending", "active", "paused", "resolved", "template", "deferred", "delegated", "recurring"}
	for _, st := range statuses {
		dir := filepath.Join(repo, st)
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			name := e.Name()
			if !strings.HasSuffix(name, ".yml") {
				continue
			}
			uuidStr := strings.TrimSuffix(name, ".yml")
			path := filepath.Join(dir, name)
			data, err := os.ReadFile(path)
			if err != nil {
				continue
			}
			task, err := parseTaskYaml(data)
			if err != nil {
				continue
			}
			task.Uuid = uuidStr
			task.Status = st
			if task.Priority == "" {
				task.Priority = "P2"
			}
			all = append(all, task)
			uuidToStatus[uuidStr] = st
			uuidToTask[uuidStr] = task
		}
	}
	return all, uuidToStatus, uuidToTask
}

func loadAndAssignIds(repo string, tasks []Task, idMap IdsMap) ([]Task, IdsMap) {
	if len(idMap) == 0 {
		openUuids := []string{}
		for _, t := range tasks {
			if t.Status != "resolved" {
				openUuids = append(openUuids, t.Uuid)
			}
		}
		sort.Strings(openUuids)
		tmp := make(map[string]int)
		for i, u := range openUuids {
			tmp[u] = i + 1
		}
		for idx := range tasks {
			if tasks[idx].Status == "resolved" {
				tasks[idx].Id = 0
			} else {
				if id, ok := tmp[tasks[idx].Uuid]; ok {
					tasks[idx].Id = id
				}
			}
		}
		return tasks, idMap
	}
	uuidExists := make(map[string]bool)
	for _, t := range tasks {
		if t.Status != "resolved" {
			uuidExists[t.Uuid] = true
		}
	}
	cleaned := make(IdsMap)
	used := make(map[int]bool)
	maxId := 0
	for uuid, id := range idMap {
		if uuidExists[uuid] {
			cleaned[uuid] = id
			used[id] = true
			if id > maxId {
				maxId = id
			}
		}
	}
	for idx := range tasks {
		if tasks[idx].Status == "resolved" {
			tasks[idx].Id = 0
			continue
		}
		if id, ok := cleaned[tasks[idx].Uuid]; ok {
			tasks[idx].Id = id
		} else {
			newId := 1
			for {
				if !used[newId] {
					break
				}
				newId++
			}
			cleaned[tasks[idx].Uuid] = newId
			used[newId] = true
			tasks[idx].Id = newId
			if newId > maxId {
				maxId = newId
			}
		}
	}
	return tasks, cleaned
}

func gitCommit(repo string, message string) error {
	cmd := exec.Command("git", "add", "-A")
	cmd.Dir = repo
	cmd.Run()
	cmd = exec.Command("git", "diff", "--cached", "--quiet")
	cmd.Dir = repo
	err := cmd.Run()
	if err == nil {
		fmt.Fprintln(os.Stdout, "\x1b[38;5;245mNo changes detected\x1b[0m")
		return nil
	}
	cmd = exec.Command("git", "commit", "-m", message)
	cmd.Dir = repo
	out, err := cmd.CombinedOutput()
	fmt.Print("\x1b[38;5;245m")
	fmt.Print(string(out))
	fmt.Print("\x1b[0m")
	return err
}

func parseQuery(args []string) Query {
	q := Query{}
	for _, a := range args {
		if a == "--" {
			q.IgnoreContext = true
			continue
		}
		if strings.HasPrefix(a, "+") {
			tag := strings.TrimPrefix(a, "+")
			if tag != "" {
				q.Tags = append(q.Tags, tag)
			}
			continue
		}
		if strings.HasPrefix(a, "-project:") {
			proj := strings.TrimPrefix(a, "-project:")
			q.AntiProjects = append(q.AntiProjects, proj)
			continue
		}
		if strings.HasPrefix(a, "-") {
			tag := strings.TrimPrefix(a, "-")
			if tag != "" {
				q.AntiTags = append(q.AntiTags, tag)
			}
			continue
		}
		if strings.HasPrefix(a, "project:") {
			proj := strings.TrimPrefix(a, "project:")
			q.Project = proj
			continue
		}
		if strings.HasPrefix(a, "due:") {
			dueStr := strings.TrimPrefix(a, "due:")
			if dueStr == "" {
				q.Due = time.Time{}
			} else {
				if t, err := parseDue(dueStr); err == nil {
					q.Due = t
				}
			}
			continue
		}
		if a == "P0" || a == "P1" || a == "P2" || a == "P3" {
			q.Priority = a
			continue
		}
		if strings.HasPrefix(a, "template:") {
			tmplStr := strings.TrimPrefix(a, "template:")
			if id, err := strconv.Atoi(tmplStr); err == nil {
				q.Template = id
			}
			continue
		}
		if q.Text != "" {
			q.Text += " "
		}
		q.Text += a
	}
	return q
}

type AddParseResult struct {
	Summary      string
	Notes        string
	Tags         []string
	Project      string
	ProjectSet   bool
	Priority     string
	PrioritySet  bool
	Due          time.Time
	DueSet       bool
	TemplateId   int
	IgnoreContext bool
}

func parseAddArgs(args []string) (AddParseResult, error) {
	res := AddParseResult{Priority: "P2"}
	slashIdx := -1
	for i, a := range args {
		if a == "/" {
			slashIdx = i
			break
		}
	}
	var before []string
	var after []string
	if slashIdx != -1 {
		before = args[:slashIdx]
		after = args[slashIdx+1:]
		res.Notes = strings.Join(after, " ")
	} else {
		before = args
	}
	filtered := []string{}
	for _, a := range before {
		if a == "--" {
			res.IgnoreContext = true
		} else {
			filtered = append(filtered, a)
		}
	}
	before = filtered
	var summaryWords []string
	for _, a := range before {
		if strings.HasPrefix(a, "+") {
			tag := strings.TrimPrefix(a, "+")
			if tag != "" {
				res.Tags = append(res.Tags, tag)
			}
			continue
		}
		if strings.HasPrefix(a, "-") {
			tag := strings.TrimPrefix(a, "-")
			newTags := []string{}
			for _, t := range res.Tags {
				if t != tag {
					newTags = append(newTags, t)
				}
			}
			res.Tags = newTags
			continue
		}
		if strings.HasPrefix(a, "project:") {
			proj := strings.TrimPrefix(a, "project:")
			res.Project = proj
			res.ProjectSet = true
			continue
		}
		if strings.HasPrefix(a, "due:") {
			dueStr := strings.TrimPrefix(a, "due:")
			if dueStr == "" {
				res.Due = time.Time{}
				res.DueSet = true
			} else {
				t, err := parseDue(dueStr)
				if err != nil {
					return res, err
				}
				res.Due = t
				res.DueSet = true
			}
			continue
		}
		if a == "P0" || a == "P1" || a == "P2" || a == "P3" {
			res.Priority = a
			res.PrioritySet = true
			continue
		}
		if strings.HasPrefix(a, "template:") {
			tmplStr := strings.TrimPrefix(a, "template:")
			if id, err := strconv.Atoi(tmplStr); err == nil {
				res.TemplateId = id
			}
			continue
		}
		summaryWords = append(summaryWords, a)
	}
	res.Summary = strings.Join(summaryWords, " ")
	return res, nil
}

func getContext(repo string) (Query, bool) {
	if envCtx := os.Getenv("DSTASK_CONTEXT"); envCtx != "" {
		q := parseQuery(strings.Fields(envCtx))
		q.Cmd = "context"
		return q, true
	}
	st := loadState(repo)
	return st.Context, false
}

func printActiveContext(q Query, fromEnv bool) {
	has := false
	var parts []string
	for _, t := range q.Tags {
		parts = append(parts, "+"+t)
		has = true
	}
	for _, t := range q.AntiTags {
		parts = append(parts, "-"+t)
		has = true
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
		has = true
	}
	for _, p := range q.AntiProjects {
		parts = append(parts, "-project:"+p)
		has = true
	}
	if !q.Due.IsZero() {
		parts = append(parts, "due:"+q.Due.Format("2006-01-02"))
		has = true
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
		has = true
	}
	if q.Template != 0 {
		parts = append(parts, fmt.Sprintf("template:%d", q.Template))
		has = true
	}
	if q.Text != "" {
		parts = append(parts, q.Text)
		has = true
	}
	if !has {
		return
	}
	ctxStr := strings.Join(parts, " ")
	if fromEnv {
		fmt.Printf("\x1b[33mActive context (set by DSTASK_CONTEXT): %s\x1b[0m\n\n", ctxStr)
	} else {
		fmt.Printf("\x1b[33mActive context: %s\x1b[0m\n\n", ctxStr)
	}
}

func getPriorityColor(priority, status string) (string, string) {
	if status == "active" {
		bg := "250"
		var fg string
		switch priority {
		case "P0":
			fg = "124"
		case "P1":
			fg = "130"
		case "P2":
			fg = "233"
		case "P3":
			fg = "245"
		default:
			fg = "233"
		}
		return fg, bg
	}
	if status == "paused" {
		bg := "236"
		var fg string
		switch priority {
		case "P0":
			fg = "160"
		case "P1":
			fg = "166"
		case "P2":
			fg = "250"
		case "P3":
			fg = "245"
		default:
			fg = "250"
		}
		return fg, bg
	}
	switch priority {
	case "P0":
		return "160", "233"
	case "P1":
		return "166", "232"
	case "P2":
		return "250", "233"
	case "P3":
		return "245", "232"
	default:
		return "250", "233"
	}
}

func truncateSummary(s string, max int) string {
	if len(s) <= max {
		return s
	}
	// cut to max, but avoid breaking?
	if max <= 0 {
		return ""
	}
	return s[:max]
}

