python3 <<'PY'
import pty, os, subprocess, select, time, json
os.environ['DSTASK_GIT_REPO']='/tmp/mod_prompt_test'
def run_pty(cmd, input_data=None):
    master, slave = pty.openpty()
    env=os.environ.copy()
    env['DSTASK_GIT_REPO']='/tmp/mod_prompt_test'
    proc=subprocess.Popen(cmd, shell=True, stdin=slave, stdout=slave, stderr=slave, env=env, cwd='/tmp/go_mod')
    os.close(slave)
    out=b""
    time.sleep(0.2)
    if input_data:
        os.write(master, input_data.encode())
    while True:
        r,_,_=select.select([master], [], [], 0.5)
        if r:
            try:
                data=os.read(master,1024)
                if not data:
                    break
                out+=data
            except:
                break
        else:
            if proc.poll() is not None:
                try:
                    while True:
                        data=os.read(master,1024)
                        if not data:
                            break
                        out+=data
                except:
                    pass
                break
    os.close(master)
    proc.wait()
    return out.decode(errors='ignore')

print(run_pty('go run . modify +extra', input_data='y\n'))
